pub fn root_as_rfs_with_opts<'b, 'o>(
  opts: &'o ::flatbuffers::VerifierOptions,
  buf: &'b [u8],
) -> Result<RFS<'b>, ::flatbuffers::InvalidFlatbuffer> {
  ::flatbuffers::root_with_opts::<RFS<'b>>(opts, buf)
}
#[inline]
/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `RFS` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_rfs_unchecked`.
pub fn size_prefixed_root_as_rfs_with_opts<'b, 'o>(
  opts: &'o ::flatbuffers::VerifierOptions,
  buf: &'b [u8],
) -> Result<RFS<'b>, ::flatbuffers::InvalidFlatbuffer> {
  ::flatbuffers::size_prefixed_root_with_opts::<RFS<'b>>(opts, buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a RFS and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `RFS`.
pub unsafe fn root_as_rfs_unchecked(buf: &[u8]) -> RFS<'_> {
  unsafe { ::flatbuffers::root_unchecked::<RFS>(buf) }
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a size prefixed RFS and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `RFS`.
pub unsafe fn size_prefixed_root_as_rfs_unchecked(buf: &[u8]) -> RFS<'_> {
  unsafe { ::flatbuffers::size_prefixed_root_unchecked::<RFS>(buf) }
}
pub const RFS_IDENTIFIER: &str = "$RFS";

#[inline]
pub fn rfs_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, RFS_IDENTIFIER, false)
}

#[inline]
pub fn rfs_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, RFS_IDENTIFIER, true)
}

#[inline]
pub fn finish_rfs_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<RFS<'a>>) {
  fbb.finish(root, Some(RFS_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_rfs_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>, root: ::flatbuffers::WIPOffset<RFS<'a>>) {
  fbb.finish_size_prefixed(root, Some(RFS_IDENTIFIER));
}
